using System;
using System.Linq;
using System.Collections.Generic;

class Program
{
    static void Main()
    {
        var lr = Console.ReadLine().Split(' ').Select(x => Int64.Parse(x)).ToArray();
        var L = lr[0];
        var R = lr[1];

        const long mod = 2019;
        var modL = L % mod;
        var modR = R % mod;

        var ans = long.MaxValue;

        var sa = R - L;
        if (mod - 1 <= sa) ans=0;
        else if (modR < modL) ans=0;
        else
        {
            var modArray = new long[R - L + 1];
            var index = 0;
            for (var i = L; i <= R; ++i)
            {
                var num = i;
                while (mod <= num)
                {
                    num %= mod;
                }
                modArray[index] = num;
                index++;
            }
            for (int i=0;i<modArray.Length;++i)
            {
                for (int j=i+1;j<modArray.Length;++j)
                {
                    var num = modArray[i] * modArray[j];
                    while (mod <= num)
                    {
                        num %= mod;
                    }
                    if (num < ans) ans = num;
                }
            }
        }
        Console.WriteLine(ans);
    }
}

