namespace ConsoleApplication22
{
    class Program
    {
        static void Main(string[] args)
        {
            String[] input = Console.ReadLine().Split(' ');
            long n = long.Parse(input[0]);
            long m = long.Parse(input[1]);
            long l = long.Parse(input[2]);
            if (n < 1 || m < 1 || l < 1)
            {
                if (n < 1)
                    n = 1;
                else if (m < 1)
                    m = 1;
                else if (l < 1)
                    l = 1;
            }
            else if (n > 101 && m > 101 && l > 101)
            {
                if (n > 100)
                    n = 100;
                else if (m > 100)
                    m = 100;
                else if (l > 100)
                    l = 100;
            }

            long[,] A = new long[n, m];
            long[,] B = new long[m, l];

            for (long y = 0; y < n; y++)
            {
                String[] input2 = Console.ReadLine().Split(' ');
                for (long x = 0; x < m; x++)
                {
                    long an = long.Parse(input2[x]);
                    if (an < 0)
                    {
                        an = 0;
                    }

                    else if (an > 10000)
                    {
                        an = 10000;
                    }

                    A[y, x] = an;
                }
            }
            for (long y = 0; y < m; y++)
            {
                String[] input3 = Console.ReadLine().Split(' ');
                for (long x = 0; x < l; x++)
                {
                    long bn = long.Parse(input3[x]);
                    if (bn < 0)
                    {
                        bn = 0;
                    }
                    else if (bn > 10000)
                    {
                        bn = 10000;
                    }
                    B[y, x] = bn;
                }
            }
            long[,] C = new long[n, l];
            long cn = 0;
            for (long z = 0; z < n; z++)
            {
                for (long y = 0; y < l; y++)
                {
                    for (long x = 0; x < m; x++)
                    {
                        cn = A[z, x] * B[x, y];
                        C[z, y] = C[z, y] + cn;
                    }
                }
            }
            for (long y = 0; y < n; y++)
            {
                for (long x = 0; x < l; x++)
                {
                    Console.Write(C[y, x]);
                    if (x != l-1)
                        Console.Write(" ");
                }
                    Console.WriteLine("");
            }
        }
    }
}

