        {
            int min = N;
            for (int i = 0; i < M; i++)
            {
                if (b[i] <= min && brg[i] == false)
                {
                    min = b[i];
                }
            }
            for (int i = 0; i < M; i++)
            {
                if (a[i] < min && min <= b[i] && brg[i] == false)
                {
                    brg[i] = true;
                    task--;
                }
            }
            bk++;
        }
        Console.WriteLine(bk);
