public class Program
{
    public static void Main()
    {
        var n = int.Parse(Console.ReadLine());
        var ps = new Tuple<long, long>[n];
        for (int i = 0; i < ps.Length; i++)
        {
            var xy = Console.ReadLine().Split().Select(x => long.Parse(x)).ToArray();
            ps[i] = Tuple.Create(xy[0], xy[1]);
        }

        Array.Sort(ps);
        Console.Error.WriteLine(string.Join(", ", ps.Select(x => $"({x.Item1}, {x.Item2})")));

        var maxCount = 0;
        for (int u = 0; u < ps.Length; u++)
        {
            for (int v = u + 1; v < ps.Length; v++)
            {
                var p = ps[u].Item1 - ps[v].Item1;
                var q = ps[u].Item2 - ps[v].Item2;

                var ts = ps.Select(x => Tuple.Create(x.Item1 - p, x.Item2 - q)).ToArray();
                Array.Sort(ts);
                int ip = 0;
                int it = 0;
                var k = 0;
                while (true)
                {
                    while (ip < ps.Length && ps[ip].Item1 < ts[it].Item1)
                    {
                        ip++;
                    }
                    if (ip >= ps.Length)
                    {
                        break;
                    }
                    while (it < ts.Length && ps[ip].Item1 > ts[it].Item1)
                    {
                        it++;
                    }
                    if (it >= ts.Length)
                    {
                        break;
                    }
                    while (ip < ps.Length && ps[ip].Item1 == ts[it].Item1 && ps[ip].Item2 < ts[it].Item2)
                    {
                        ip++;
                    }
                    if (ip >= ps.Length)
                    {
                        break;
                    }
                    while (it < ts.Length && ps[ip].Item1 == ts[it].Item1 && ps[ip].Item2 > ts[it].Item2)
                    {
                        it++;
                    }
                    if (it >= ts.Length)
                    {
                        break;
                    }
                    if (ps[ip].Item1 != ts[it].Item1 || ps[ip].Item2 != ts[it].Item2)
                    {
                        continue;
                    }

                    k++;
                    ip++;
                    it++;
                }
                maxCount = Math.Max(maxCount, k);
            }
        }

        Console.WriteLine(n - maxCount);
    }
}

