using namespace std;

int main() {
  string s;
  cin >> s;
  vector<int> v;
  v.push_back(0);
  for (int i = 0; i < s.size(); i++) {
    if (s[i] == '<')
      v.push_back(v[i]+1);
    if (s[i] == '>') {
      v.push_back(v[i]-1);
    }
  }

  int min = 0;
  for (int i = 0; i < v.size(); i++) {
    if (v[i] < min)
      min = v[i];
  }

  for (int i = 0; i < v.size(); i++)
    v[i] -= min;

  if (s[0] == '<')
    v[0] = 0;
  if (s.back() == '>')
    v.back() = 0;
  for (int i = 0; i < s.size(); i++) {
    if (s[i] == '>' && s[i+1] == '<')
      v[i+1] = 0;
  }

  if (DEBUG >= 2) {
    for (int i = 0; i < v.size(); i++)
      cout << v[i] << " ";
    cout << endl;
  }

  int l = 0, r = -1;
  bool flag = false;
  for (int i = 1; i < v.size(); i++) {
    if (v[i] == 0 || i  == v.size() - 1) {
      r = (i == v.size() - 1 && v.back() != 0) ? v.size() : i;
      flag = true;
      if (flag) {
        if (DEBUG >= 2) {
       	 cout << "L:" << l << " R:" << r << endl;
        }
        if (l + 2 == r && l != 0) {
          v[l+1] = 1;
      	  l = r;
      	  r = -1;
          continue;
        }
        int sl = (l == 0 && v[0] != 0) ? l : l + 1, sr = sl;
        char sign = s[sr];
        while (1) {
          while (sr <= v.size() && v[sr + 1] != 0 && s[++sr] == sign) {}
          if (DEBUG >= 2) {
            cout << "v[" << sl << "] = " << v[sl] << " " << sign << " v[" << sr << "] = " << v[sr] << endl;
            for (int k = sl; k <= sr; k++)
              cout << v[k] << " ";
            cout << endl;
          }
          int d;
          if (sign == '<') {
            if (sr + 1 != r)
              sr--;
          	d = v[sl] - 1;
          }
          else {
            if (sl != 0)
          	  sl++;
            d = v[sr] - 1;
          }
          d = std::max(0, d);
          if (DEBUG >= 2) {
            cout << "d = " << d << endl;
          }
          for (int j = sl; j <= sr; j++)
            v[j] -= d;
          if (sign == '<') {
            sign = '>';
            sl = sr + 1;
            sr = sl;
          }
          else {
            sign = '<';
            sl = l == sl ? sr + 1 : sr;
            sr = sl;
          }
          if (sr + 1 >= r)
        	  break;
        }
        l = r;
        r = -1;
        flag = false;
      }
    }
  }

  for (int i = 0; i < s.size() - 1; i++) {
    if (s[i] == '<' && s[i+1] == '>') {
      v[i+1] = std::max(v[i], v[i+2]) + 1;
    }
  }

  if (DEBUG >= 1) {
    for (int i = 0; i < s.size(); i++)
      cout << v[i] << " " << s[i] << " ";
    cout << v.back() << endl;
  }

  ll total = 0;
  for (int i = 0; i < v.size(); i++)
    total += v[i];

  cout << total << endl;

  return 0;
}

