		Map<Integer, Integer> bri = new HashMap<>();
		for(int i = 0; i < m; i++) {
			int a = sc.nextInt();
			int b = sc.nextInt();
			if(bri.containsKey(a)) {
				int val = bri.get(a);
				bri.put(a, Math.min(val, b));
			} else {
				bri.put(a, b);
			}
		}
		int ans = 0;
		while(!bri.isEmpty()) {
			int b = (int) Math.pow(10, 5);
			for(Map.Entry<Integer, Integer> e : bri.entrySet()) {
				if(e.getValue() < b) {
					b = e.getValue();
				}
			}
			ans++;
			for(int i = 1; i < b; i++) {
				if(bri.containsKey(i)) {
					bri.remove(i);
				}
			}
		}
		System.out.println(ans);
	}

