int main(){
    int n;
    cin >> n;
    vector<int> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    sort(a.begin(), a.end());
    int p = a.back();
    if (p % 2){
        int ok = n;
        int ng = - 1;
        while (abs(ok - ng) > 1){
            int mid = (ok + ng) / 2;
            if (a[mid] >= p / 2) ok = mid;
            else ng = mid;
        }
        if (ok + 1 == n) ok--;
        int ok2 = n;
        int ng2 = - 1;
        while (abs(ok2 - ng2) > 1){
            int mid2 = (ok2 + ng2) / 2;
            if (a[mid2] >= p / 2 + 1) ok2 = mid2;
            else ng2 = mid2;
        }
        if (ok2 + 1 == n) ok2--;
        int x, y;
        if (ok - 1 >= 0 && a[ok] - p / 2 > p / 2 - a[ok - 1]) x = a[ok - 1];
        else x = a[ok];
        if (ok2 - 1 >= 0 && a[ok2] - p / 2 - 1 > p / 2 + 1 - a[ok2 - 1]) y = a[ok2 - 1];
        else y = a[ok2];
        if (abs(x - p / 2) > abs(y - p / 2 - 1)) cout << p << " " << y << endl;
        else cout << p << " " << x << endl;
    }
    else{
        int ok = n;
        int ng = - 1;
        while (abs(ok - ng) > 1){
            int mid = (ok + ng) / 2;
            if (a[mid] >= p / 2) ok = mid;
            else ng = mid;
        }
        if (ok + 1 == n) ok--;
        if (ok - 1 >= 0 && a[ok] - p / 2 > p / 2 - a[ok - 1]) cout << p << " " << a[ok - 1] << endl;
        else cout << p << " " << a[ok] << endl;
    }
}

