import static java.lang.System.*;
import java.util.*;

public class Main {
	static Scanner sc = new Scanner(System.in);
	static List<Integer> list = new ArrayList<>();
	static int num = 0;


	public static void main(String[] args) {
		int n = sc.nextInt();
		for (int i=0; i<n; i++) list.add(sc.nextInt());

		mergeSort(list);

		StringBuilder sb = new StringBuilder();
		for (int i=0; i<list.size(); i++) sb.append((i==0?"":" ")+list.get(i));
		out.println(sb);
		out.println(num);
	}


	static void mergeSort(List<Integer> list) {
		int size = list.size();

		//listの大きさが1なら再帰終了
		if (size == 1) return;

		//1でないなら分割
		ArrayList<Integer> L = new ArrayList<>(), R = new ArrayList<>();
		int M = size/2;

			//分割処理、左側を作成
			for (int i=0; i<M; i++) L.add(list.get(i));
			//分割処理、右側を作成
			for (int i=M; i<size; i++) R.add(list.get(i));


		//再帰
		mergeSort(L); mergeSort(R);

		//マージ処理
		list.clear();
		int indexL = 0, indexR = 0;
		while (indexL<L.size() || indexR<R.size()) {
			if (indexL == L.size()) {
				list.add(R.get(indexR)); indexR++; num++;
			}
			else if (indexR == R.size()) {
				list.add(L.get(indexL)); indexL++; num++;
			}
			else {
				int tempL = L.get(indexL);
				int tempR = R.get(indexR);
				if (tempL <= tempR) {
					list.add(tempL); indexL++;
				}
				else {
					list.add(tempR); indexR++;
				}
				num++;
			}
		}
	}
}

import java.util.Arrays;
import java.util.Scanner;

class Main{
	public static void main(String[] args) {
		Scanner sc=new Scanner(System.in);
		int M=sc.nextInt();	//数字の種類
		int N=sc.nextInt();	//部分和にしたい数
		int[] A=new int[N];	//数字
		int[] C=new int[N];	//数字の個数
		int[] dp=new int[M+1];
		if(N==1) {
			System.out.println(M);
			System.exit(0);
		}
		int max=0;
		//boolean[] kousin=new boolean[M+1];		//値の更新を無限回行わないようにすでに更新を行ったか？のフラグ
		Arrays.fill(dp, -1); 	//dpを0で埋めると0枚で払えると混同する（工夫すれば0フィルでも行けそうだけど）
		for(int i=0; i<N; i++) {
			A[i]=sc.nextInt();
			max=Math.max(max,A[i] );
		}
		for(int i=0; i<N; i++) {
			if(A[i]==1) {
				C[i]=max;
			}
			else {
				C[i]=(M+A[i]-1)/A[i];
			}
		}
		if(M%max==0) {
			System.out.println(M/max);
			System.exit(0);
		}
		dp[0]=0;	//いつもの
		for(int i=0; i<N; i++) {
			for(int j=M; j>=0; j--) {		//すでにお金の払い方として成立する場合で、払う枚数の最小を更新する時に、更新した値で更に更新しないように高い値から処理していく
				if(dp[j]>=0) {
					int roop=Math.min(C[i],(M-j)/A[i]);
					for(int k=roop; k>=0; k--) {	//使用限度を守っていてなおかつ求めたい額よりも少ない
						if(dp[j+k*A[i]]==-1) {	//いままでのお金だと払えなかった時
							dp[j+k*A[i]]=dp[j]+k;
						}
						else if(dp[j+k*A[i]]>=0) {	//より少ない枚数でお金をちょうど出せるか？
							dp[j+k*A[i]]=Math.min(dp[j+k*A[i]], dp[j]+k);
							//kousin[j+k*A[i]]=true;	//すでにお金の払い方として成立するので更新には入らない
						}
					}
				}
			}
		}
		/*int cnt=0;
		for(int i=1; i<=M; i++) {
			if(dp[i]>=0) {
				//System.out.println(i+" "+dp[i]);
				cnt++;
			}
		}*/
		System.out.println(dp[M]);
	}
}

