def read_values(): return map(int, input().split())
def read_index(): return map(lambda x: int(x) - 1, input().split())
def read_list(): return list(read_values())
def read_lists(N): return [read_list() for n in range(N)]


def main():
    N = int(input())
    T = read_lists(N)
    Q = []
    for a, b in T:
        heapq.heappush(Q, (a, -1))
        heapq.heappush(Q, (b, 1))

    K1 = (N - 1) // 2 + 1
    K2 = N // 2 + 1

    s = 0
    t = 0
    S = [0, 0]
    T = [0, 0]
    while s < K2:
        a, k = heapq.heappop(Q)
        if k < 0:
            t += 1
        else:
            t -= 1
            s += 1

        if S[0] == 0 and s + t >= K1:
            S[0] = a

        if S[1] == 0 and s >= K1:
            S[1] = a

        if T[0] == 0 and s + t >= K2:
            T[0] = a

        if T[1] == 0 and s >= K2:
            T[1] = a

    if N % 2 == 1:
        print(S[1] - S[0] + 1)
    else:
        print((S[1] + T[1]) - (S[0] + T[0]) + 1)


