		while(sc.hasNext()){
			input.addLast(sc.next());
		}
		LinkedList<String> rest = new LinkedList<String>();

		while(!input.isEmpty()){
			//System.out.println(input + " " + rest);
			final int a = Integer.parseInt(input.poll());
			if(input.isEmpty()){
				System.out.println(a);
				break;
			}

			final int b = Integer.parseInt(input.poll());
			final String ops = input.poll();

			if("+".equals(ops)){
				input.addFirst((a + b) + "");
				while(!rest.isEmpty()){
					input.addFirst(rest.poll());
				}
			}else if("-".equals(ops)){
				input.addFirst((a - b) + "");
				while(!rest.isEmpty()){
					input.addFirst(rest.poll());
				}
			}else if("*".equals(ops)){
				input.addFirst((a * b) + "");
				while(!rest.isEmpty()){
					input.addFirst(rest.poll());
				}
			}else if("/".equals(ops)){
				input.addFirst((a / b) + "");
				while(!rest.isEmpty()){
					input.addFirst(rest.poll());
				}
			}else{
				rest.addFirst(a + "");
