import java.util.*;
class Main{ 
        public static void main(String[] args){ 
            Scanner sc = new Scanner(System.in); 
            int n = sc.nextInt(); Card A[] = new Card[n]; 
            for(int i=0; i<n; i++){ 
                A[i] = new Card(); 
                A[i].pic = sc.next(); 
                A[i].num = sc.nextInt(); 
                A[i].idx = i; 
            } 
            quicksort(A, 0, n-1); 
            int flg=0, off; 
            int I[] = new int[4]; 
            for(int i=0; i<n; i+=off){ 
                I[0] = A[i].idx; 
                off = 1; 
                while(i+off<n && A[i].num==A[i+off].num) { 
                    I[off] = A[i+off].idx; 
                    off++; 
                } 
                if(off != 1){ 
                    for(int j=0; j<off-1; j++) { 
                        for(int k=j+1; k<off; k++){ 
                            if(I[j] > I[k]){ 
                                flg = 1; 
                                break; 
                            } 
                        } 
                        if(flg == 1) 
                            break; 
                    } 
                } 
                if(flg == 1) 
                    break; 
            } 
            if(flg == 0) 
                System.out.println("Stable"); 
            else System.out.println("Not stable"); 
            for(int i=0; i<n; i++){ 
                System.out.println(A[i].pic+" "+A[i].num); 
            } 
        } 
        static void quicksort(Card A[], int p, int r){ 
            if(p < r) { 
                int q = partition(A, p, r); 
                quicksort(A, p, q-1); 
                quicksort(A, q+1, r); 
            } 
        } 
        static int partition(Card A[], int p, int r){ 
            Card work; 
            int i = p-1; 
            for(int j=p; j<=r-1; j++){ 
                if(A[j].num <= A[r].num){ 
                    i++;
                    work = A[i];
                    A[i] = A[j];
                    A[j] = work; 
                } 
            } 
            i++; 
            work = A[i]; 
            A[i] = A[r]; 
            A[r] = work; 
            return i; 
        } 
    } 
    class Card{ 
        String pic; 
        int num; 
        int idx; 
    }

import java.util.Arrays;
import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		// Shojin
		try (Scanner sc = new Scanner(System.in)) {
			int n = sc.nextInt();
			long k = sc.nextLong();
			Long[] A = new Long[n];
			long tmp = 0;
			for (int i = 0; i < n; i++) {
				long next = sc.nextLong();
				A[i] = next;
				tmp += next;
			}
			final long sum = tmp;
			Arrays.sort(A, (x, y) -> x / ((x * k / sum) + 1) > y / ((y * k / sum) + 1) ? 1 : -1);
			if (k == 0) {
				System.out.println(A[n - 1]);
				return;
			}
			int[] cutCnt = new int[n];
			int cutCntSum = 0;
			for (int i = 0; i < n; i++) {
				long cnt = A[i] * k / sum;
				cutCnt[i] = (int) cnt;
				cutCntSum += (int) cnt;
			}
			long ans = 0;
			for (int i = n - 1; i >= 0; i--) {
				if (cutCntSum < k) {
					cutCnt[i]++;
					cutCntSum++;
				}
				if (cutCnt[i] == 0) {
					ans = Math.max(ans, A[i]);
					continue;
				}
				if (A[i] % cutCnt[i] == 0) {
					ans = Math.max(ans, A[i] / (cutCnt[i] + 1));
				} else {
					ans = Math.max(ans, A[i] / (cutCnt[i] + 1) + 1);
				}
			}
			System.out.println(ans);
		}
	}
}

