void InOrder() {
    if (m_root == null) {
        return;
    }
    Stack<BSTNode> myStack = new Stack<BSTNode>();
    BSTNode current = m_root;
    PushAllLeftNodes(current, myStack);
    while (myStack.Count != 0) {
        current = myStack.Pop();
        Console.Write(current.Info + " ");
        if (current.Right != null) {
            PushAllLeftNodes(current.Right, myStack);
        }
    }
}

void PushAllLeftNodes(BSTNode current, Stack<BSTNode> stack) {
    while (current != null) {
        stack.Push(current);
        current = current.Left;
    }
}

