    for (int i = 0;
    i < positions.size (); i ++) {
        turns.add (null);
    }
    int counter = 0;
    if (positions.size () > 2) {
        Point base = positions.get (0);
        Point next = positions.get (1);
        int x = (next.x - base.x);
        double slope = 1.0 * (next.y - base.y) / (next.x - base.x);
        for (int i = 2;
        i < positions.size (); i ++) {
            Point newpoint = positions.get (i);
            double newslope = 1.0 * (newpoint.y - next.y) / (newpoint.x - next.x);
            if (newslope != slope) {
