import json
from operator import attrgetter

class Location:
    def __init__(self, lon, lat, desc):
        self.lon = lon
        self.lat = lat
        self.desc = desc

    def __eq__(self, other):
        return self.lon == other.lon and self.lat == other.lat

    def __str__(self):
        return json.dumps(self, default=lambda o: o.__dict__)

s = [{"lon": 0.001, "lat": 0.001, "desc": "test"},{"lon": 0.002, "lat": 0.001, "desc": "test3"},{"lon": 0.002, "lat": 0.005, "desc": "test4"},{"lon": 0.002, "lat": 0.001, "desc": "test5"},{"lon": 0.001, "lat": 0.001, "desc": "test2"}]
al = [Location(**i) for i in s]
al.sort(key=attrgetter('lon', 'lat'))
fl = []
current = None

for loc in al:
    if current is None or not current == loc:
        current = loc
        fl.append(current)
    else:
        current.desc += ',' + loc.desc
print([str(i) for i in fl])

