class GFG {
  static int sumofFactors ( int n ) {
    int res = 1 ;
    for ( int i = 2 ;
    i <= Math . sqrt ( n ) ;
    i ++ ) {
      int count = 0 , curr_sum = 1 ;
      int curr_term = 1 ;
      while ( n % i == 0 ) {
        count ++ ;
        n = n / i ;
        curr_term *= i ;
        curr_sum += curr_term ;
      }
      res *= curr_sum ;
    }
    if ( n >= 2 ) res *= ( 1 + n ) ;
    return res ;
  }
  static int gcd ( int a , int b ) {
    if ( a == 0 ) return b ;
    return gcd ( b % a , a ) ;
  }
  static boolean checkFriendly ( int n , int m ) {
    int sumFactors_n = sumofFactors ( n ) ;
    int sumFactors_m = sumofFactors ( m ) ;
